#---Testsing the data handling functions---
class TestDataHandling:
    def test_clean_columns_replaces_underscores_and_titles(self):
        df = pd.DataFrame({"test_column_name": [1, 2], "another_col": [3, 4]})
        cleaned = clean_columns(df.copy())
        assert "Test Column Name" in cleaned.columns
        assert "Another Col" in cleaned.columns

    def test_convert_percentage_to_numeric_converts_strings_with_percentage(self):
        df = pd.DataFrame({"Pct": ["50%", "25%", "100%"], "Other": [1, 2, 3]})
        output = convert_percentage_to_numeric(df.copy(), "Pct")
        assert output["Pct"].dtype.kind in "fi"
        assert output["Pct"].tolist() == [0.5, 0.25, 1.0]

    def test_convert_percentage_to_numeric_no_percentage_leaves_values_untouched(self):
        df = pd.DataFrame({"Pct": ["0.5", "0.25"], "Other": [1, 2]})
        output = convert_percentage_to_numeric(df.copy(), "Pct")
        assert output["Pct"].tolist() == ["0.5", "0.25"]

    def test_convert_percentage_to_numeric_numeric_dtype_no_change(self):
        df = pd.DataFrame({"Pct": [0.5, 0.25], "Other": [1, 2]})
        output = convert_percentage_to_numeric(df.copy(), "Pct")
        assert output["Pct"].tolist() == [0.5, 0.25]

    def test_population_to_numeric_removes_commas_and_converts_to_float(self):
        df = pd.DataFrame({"Population": ["1,000", "10,000", "0"], "Other": [1, 2, 3]})
        output = population_to_numeric(df.copy(), "Population")
        assert output["Population"].tolist() == [1000.0, 10000.0, 0.0]
        assert output["Population"].dtype.kind == "f"

    def test_population_to_numeric_already_numeric_does_not_raise(self):
        df = pd.DataFrame({"Population": [1000.0, 2000.0]})
        output = population_to_numeric(df.copy(), "Population")
        assert output["Population"].tolist() == [1000.0, 2000.0]

    def test_population_cleaning_filters_london_borough_and_renames_and_converts(self):
        df = pd.DataFrame(
            {
                "Geography": ["London Borough", "Country", "London Borough"],
                "Name": ["A", "B", "C"],
                "Mid-2024": ["1,000", "2,000", "3,500"],
                "Extra": [9, 8, 7],
            }
        )
        cleaned = population_cleaning(df)
        assert set(cleaned.columns) == {"Borough", "Population"}
        assert cleaned["Borough"].tolist() == ["A", "C"]
        assert cleaned["Population"].tolist() == [1000.0, 3500.0]

    def test_safe_streets_cleaning_selects_and_renames_fields(self):
        df = pd.DataFrame(
            {
                "Borough": ["A", "B"],
                "Ltn 2024": [1, 2],
                "20Mph 2024": [3, 4],
                "Cpz 2024": [5, 6],
                "Protected Cycle Track 2024": [7, 8],
                "School Streets 2024": [9, 10],
                "Bus Priority 2024": [11, 12],
                "Unneeded": [99, 99],
            }
        )
        cleaned = safe_streets_cleaning(df)
        expected_columns = {
            "Borough",
            "Low Traffic Neighbourhood Area As Proportion Of Total Appropriate Area",
            "Proportion Of Borough Roads With 20Mph Speed Limit %",
            "Cpz Area As Proportion Of Total Appropriate Area",
            "Protected Cycle Track (Km Per Km Of Road Length) %",
            "School Streets As Proportion Of Total Schools %",
            "Bus Route Length On Bus Lanes & Through Ltns As Proportion Of Total Bus Lane Length %",
        }
        assert set(cleaned.columns) == expected_columns
        assert cleaned.shape == (2, 7)

    def test_safe_streets_cleaning_missing_columns_raises_keyerror(self):
        df = pd.DataFrame({"Borough": ["A"]})
        with pytest.raises(KeyError):
            safe_streets_cleaning(df)

    def test_merge_datasets_computes_debt_per_capita_and_percentage_employed(self):
        safe_streets_df = pd.DataFrame(
            {
                "Borough": ["A", "B"],
                "Low Traffic Neighbourhood Area As Proportion Of Total Appropriate Area": [0.1, 0.2],
            }
        )
        population_df = pd.DataFrame(
            {"Borough": ["A", "B"], "Population": [1000.0, 2000.0]}
        )
        employees_and_debt_df = pd.DataFrame(
            {"Borough": ["A", "B"], "Debt In Gbp": [1000.0, 2000.0], "Number Of Employees": [10, 20]}
        )
        merged = merge_datasets(safe_streets_df, population_df, employees_and_debt_df)
        assert "Debt Per Capita" in merged.columns
        assert "Percentage Of Population Employed" in merged.columns
        assert merged.loc[merged["Borough"] == "A", "Debt Per Capita"].iloc[0] == 1.0
        assert merged.loc[merged["Borough"] == "B", "Percentage Of Population Employed"].iloc[0] == 1.0

    def test_merge_datasets_with_zero_population_returns_inf(self):
        safe_streets_df = pd.DataFrame(
            {"Borough": ["A"], "Low Traffic Neighbourhood Area As Proportion Of Total Appropriate Area": [0.1]}
        )
        population_df = pd.DataFrame({"Borough": ["A"], "Population": [0.0]})
        employees_and_debt_df = pd.DataFrame(
            {"Borough": ["A"], "Debt In Gbp": [1000.0], "Number Of Employees": [10]}
        )
        merged = merge_datasets(safe_streets_df, population_df, employees_and_debt_df)
        assert merged.loc[0, "Debt Per Capita"] in [float("inf"), float("nan")]

    def test_load_and_clean_data_reads_csv_and_processes_percent_columns(self, tmp_path):
        file = tmp_path / "test.csv"
        file.write_text(
            "borough_name,percentage_one,normal_col\nA,50%,1\nB,25%,2\n"
        )
        result = load_and_clean_data(str(file))
        assert "Borough Name" in result.columns
        assert "Percentage One" in result.columns
        assert result["Percentage One"].tolist() == [0.5, 0.25]

    def test_load_and_clean_data_raises_file_not_found(self):
        with pytest.raises(FileNotFoundError):
            load_and_clean_data("does_not_exist.csv")



#---Testing the contacts page functions---
class TestContactsPage:
    @pytest.mark.parametrize(
        "borough,expected",
        [
            ("Barking & Dagenham", "https://www.lbbd.gov.uk/contact-us/"),
            ("Hackney", "https://hackney.gov.uk/contact-us"),
            ("Havering", "https://www.havering.gov.uk/contactus"),
            ("Newham", "https://www.newham.gov.uk/contact-information"),
            ("Redbridge", "https://www.redbridge.gov.uk/contact-us/"),
            ("Tower Hamlets", "https://www.towerhamlets.gov.uk/content_pages/contact_us/contact-us.aspx"),
            ("Waltham Forest", "https://www.walthamforest.gov.uk/contact-us"),
        ],
    )
    def test_display_contact_info_links_for_known_boroughs(self, monkeypatch, borough, expected):
        captured = []
        monkeypatch.setattr(st, "page_link", lambda link, label=None, icon=None, disabled=None: captured.append(link))
        display_contact_info(borough)
        assert captured and captured[0] == expected

    @pytest.mark.parametrize(
        "borough,expected",
        [
            ("Barking & Dagenham", "https://www.lbbd.gov.uk/council-and-democracy/voting-and-elections/how-vote"),
            ("Hackney", "https://www.hackney.gov.uk/council-and-elections/elections-and-voting/register-vote"),
            ("Havering", "https://www.havering.gov.uk/elections-voting"),
            ("Newham", "https://www.newham.gov.uk/council/register-vote-1/3"),
            ("Redbridge", "https://www.redbridge.gov.uk/voting-and-elections/register-to-vote/"),
            ("Tower Hamlets", "https://www.towerhamlets.gov.uk/lgnl/council_and_democracy/elections__voting/elections__voting.aspx"),
            ("Waltham Forest", "https://www.walthamforest.gov.uk/voting-and-elections"),
        ],
    )
    def test_display_voting_info_links_for_known_boroughs(self, monkeypatch, borough, expected):
        captured = []
        monkeypatch.setattr(st, "page_link", lambda link, label=None, icon=None, disabled=None: captured.append(link))
        display_voting_info(borough)
        assert captured and captured[0] == expected

    def test_display_contact_info_unknown_borough_uses_empty_link(self, monkeypatch):
        captured = []
