    def test_display_voting_info_unknown_borough_uses_empty_link(self, monkeypatch):
        captured = []
        monkeypatch.setattr(st, "page_link", lambda link, label=None, icon=None, disabled=None: captured.append(link))
        display_voting_info("Unknown Borough")
        assert captured and captured[0] == ""


